<?php
$titulo='Mesas';require_once 'header.php';
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  validarCsrf();$accion=$_POST['accion']??'';$id=(int)($_POST['id']??0);
  if($accion==='estado'){$estado=$_POST['estado'];if(!in_array($estado,['libre','ocupada','reservada'],true))throw new RuntimeException('Estado no válido.');$st=$conn->prepare("SELECT estado,nombre FROM mesas WHERE id=?");$st->bind_param('i',$id);$st->execute();$mesaAntes=$st->get_result()->fetch_assoc();if(!$mesaAntes)throw new RuntimeException('Mesa no encontrada.');$estadoAnterior=$mesaAntes['estado'];$st=$conn->prepare("UPDATE mesas SET estado=? WHERE id=?");$st->bind_param('si',$estado,$id);$st->execute();if($estado!==$estadoAnterior)registrarHistorial($conn,'mesas','cambiar_estado','Estado de mesa cambiado',['mesa_id'=>$id,'nombre'=>$mesaAntes['nombre'],'estado_anterior'=>$estadoAnterior,'estado_nuevo'=>$estado]);flash('success','Estado de mesa actualizado.');}
  if($accion==='nombre'){$nombre=trim($_POST['nombre']??'');if($nombre==='')throw new RuntimeException('El nombre de la mesa no puede quedar vacío.');$st=$conn->prepare("SELECT nombre FROM mesas WHERE id=?");$st->bind_param('i',$id);$st->execute();$mesaAntes=$st->get_result()->fetch_assoc();$nombreAnterior=$mesaAntes['nombre']??('Mesa '.$id);if($nombre===$nombreAnterior){flash('success','El nombre de mesa no cambió.');}else{$st=$conn->prepare("UPDATE mesas SET nombre=? WHERE id=?");$st->bind_param('si',$nombre,$id);$st->execute();$st=$conn->prepare("SELECT id FROM pedidos WHERE mesa_id=? AND estado='abierto' ORDER BY id DESC LIMIT 1");$st->bind_param('i',$id);$st->execute();$pedidoMesa=$st->get_result()->fetch_assoc();registrarHistorial($conn,'mesas','cambiar_nombre','Nombre de mesa cambiado',['mesa_id'=>$id,'nombre_anterior'=>$nombreAnterior,'nombre_nuevo'=>$nombre,'pedido'=>$pedidoMesa?(int)$pedidoMesa['id']:null]);flash('success','Nombre de mesa actualizado y registrado en historial.');}}
  if($accion==='borrar_cuenta'){$st=$conn->prepare("SELECT m.nombre,pe.id pedido_id,pe.total FROM mesas m LEFT JOIN pedidos pe ON pe.mesa_id=m.id AND pe.estado='abierto' WHERE m.id=? ORDER BY pe.id LIMIT 1");$st->bind_param('i',$id);$st->execute();$p=$st->get_result()->fetch_assoc();if(!$p)throw new RuntimeException('Mesa no encontrada.');if(!empty($p['pedido_id'])){$st=$conn->prepare("UPDATE pedidos SET estado='anulado' WHERE id=?");$st->bind_param('i',$p['pedido_id']);$st->execute();}$st=$conn->prepare("UPDATE mesas SET estado='libre' WHERE id=?");$st->bind_param('i',$id);$st->execute();registrarHistorial($conn,'mesas','borrar_cuenta','Cuenta de mesa anulada desde Mesas',['mesa_id'=>$id,'nombre'=>$p['nombre'],'pedido'=>!empty($p['pedido_id'])?(int)$p['pedido_id']:null,'total'=>(float)($p['total']??0)]);flash('success','Cuenta anulada y mesa liberada.');}
  redir('mesas.php');
 }
}catch(Throwable $e){flash('error',$e->getMessage());redir('mesas.php');}
$ms=$conn->query("SELECT m.*,COALESCE((SELECT pe.id FROM pedidos pe WHERE pe.mesa_id=m.id AND pe.estado='abierto' ORDER BY pe.id LIMIT 1),0) pedido_id,COALESCE((SELECT SUM(pe.total) FROM pedidos pe WHERE pe.mesa_id=m.id AND pe.estado='abierto'),0) cuenta FROM mesas m ORDER BY m.id");
?>
<div class="toolbar"><div><h2>Mesas</h2><p>Ponle un nombre a la mesa o al cliente. Al cerrar y cobrar la cuenta, el nombre se limpia automáticamente para que la mesa quede lista para la siguiente atención.</p></div></div>
<div class="table-grid large"><?php while($m=$ms->fetch_assoc()):?><article class="table-card <?=$m['estado']?>"><div><strong><?=e($m['nombre'])?></strong><span><?=e($m['estado'])?></span></div><div class="mesa-total"><?=((float)$m['cuenta']>0)?dinero((float)$m['cuenta']):'Sin cuenta'?></div><div class="actions"><?php if($m['pedido_id']):?><a class="btn primary small" href="ventas.php?mesa=<?=$m['id']?>&pedido=<?=$m['pedido_id']?>">Modificar cuenta</a><a class="btn small" href="ventas.php?mesa=<?=$m['id']?>&pedido=<?=$m['pedido_id']?>">Cobrar</a><form method="post" onsubmit="return confirm('¿Borrar/anular la cuenta de esta mesa?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="accion" value="borrar_cuenta"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn danger small">Borrar</button></form><?php else:?><a class="btn primary small" href="ventas.php?mesa=<?=$m['id']?>">Abrir cuenta</a><?php endif;?></div><form method="post" class="state-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="accion" value="estado"><input type="hidden" name="id" value="<?=$m['id']?>"><select name="estado" onchange="this.form.submit()"><option value="libre" <?=$m['estado']==='libre'?'selected':''?>>Libre</option><option value="ocupada" <?=$m['estado']==='ocupada'?'selected':''?>>Ocupada</option><option value="reservada" <?=$m['estado']==='reservada'?'selected':''?>>Reservada</option></select></form><form method="post" class="mini-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="accion" value="nombre"><input type="hidden" name="id" value="<?=$m['id']?>"><input name="nombre" value="<?=e($m['nombre'])?>" maxlength="100" placeholder="Ej: Juan, Familia Pérez..." aria-label="Nombre de la mesa o cliente"><button class="btn small">Actualizar nombre</button></form></article><?php endwhile;?></div>
<?php require_once 'footer.php';?>
